CONSOLE_HTML = b"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ohbs-image Control Plane</title><link rel="stylesheet" href="/console.css"></head><body>
<a class="skip" href="#workspace">Skip to workspace</a><header class="topbar"><div class="brand"><span class="mark">O</span><div><b>ohbs-image Control Plane</b><small>GOLDEN IMAGE OPERATIONS</small></div></div><form id="session" class="session" autocomplete="off"><label for="token">Bearer token</label><input id="token" type="password" required placeholder="Memory-only token"><button type="submit">Connect</button><button id="disconnect" class="secondary" type="button">Disconnect</button></form></header>
<div class="shell"><aside><nav aria-label="Console sections"><button class="nav active" data-view="overview">Overview</button><button class="nav" data-view="runs">Runs &amp; evidence</button><button class="nav" data-view="traces">Traces</button><button class="nav" data-view="lineage">Lineage</button><button class="nav" data-view="policies">Policies</button><button class="nav" data-view="approvals">Approvals</button></nav><div id="connection" class="connection" role="status">Disconnected</div></aside>
<main id="workspace"><div class="pagehead"><div><h1 id="view-title">Operations overview</h1><p id="view-copy">Current registry health and actionable platform state.</p></div><button id="refresh" type="button">Refresh</button></div><div id="notice" class="notice" role="status">Enter a token to connect. It is never stored by the browser.</div>
<section id="overview" class="view active"><div class="metrics"><article><span>Artifacts</span><strong id="total">-</strong></article><article><span>Active</span><strong id="active">-</strong></article><article><span>Quarantined</span><strong id="quarantined">-</strong></article><article><span>Runs</span><strong id="run-count">-</strong></article><article><span>Success rate</span><strong id="success-rate">-</strong></article><article><span>Run P95</span><strong id="run-p95">-</strong></article><article><span>Failed runs</span><strong id="failed-runs">-</strong></article><article><span>Replica errors</span><strong id="replica-errors">-</strong></article><article><span>Queued rebuilds</span><strong id="rebuild-count">-</strong></article></div><div class="panel"><div class="panelhead"><h2>Artifact registry</h2><div class="filters"><label for="artifact-search">Search</label><input id="artifact-search" placeholder="ID, bucket or version"><label for="bucket">Bucket</label><input id="bucket" placeholder="All authorized"></div></div><div class="tablewrap"><table><thead><tr><th>Artifact</th><th>Bucket</th><th>Version</th><th>Status</th><th>Created</th></tr></thead><tbody id="artifact-rows"></tbody></table></div></div></section>
<section id="runs" class="view"><div class="masterdetail"><div class="panel"><h2>Recent runs</h2><div id="run-list" class="list"></div></div><div class="panel detail"><h2>Run detail</h2><div id="run-detail" class="empty">Select a run to inspect evidence.</div></div></div></section>
<section id="traces" class="view"><div class="panel"><div class="panelhead"><h2>Recent spans</h2><div class="filters"><label for="trace-search">Trace ID</label><input id="trace-search" placeholder="Exact trace ID"></div></div><div id="trace-list" class="list"></div></div></section>
<section id="lineage" class="view"><div class="masterdetail"><div class="panel"><h2>Artifact lineage</h2><div id="lineage-list" class="list"></div></div><div class="panel detail"><h2>Impact analysis</h2><div id="lineage-detail" class="empty">Select an artifact to inspect ancestry and blast radius.</div></div></div></section>
<section id="policies" class="view"><div class="masterdetail"><div class="panel"><h2>Policy registry</h2><div id="policy-list" class="list"></div></div><div class="panel detail"><h2>Candidate policy studio</h2><p class="hint">Edit JSON, then validate, diff and simulate before requesting publication approval.</p><label for="policy-environment">Environment</label><input id="policy-environment" value="production"><label for="policy-editor">Candidate bundle</label><textarea id="policy-editor" class="policy-editor" spellcheck="false" placeholder="Select a policy or paste a policy bundle"></textarea><div class="actions"><button id="policy-diff" type="button">Preview diff</button><button id="policy-simulate" type="button">Simulate impact</button><button id="exception-preview" type="button">Exception lifecycle</button><button id="policy-request" type="button">Request publication</button></div><div id="policy-result" class="simulation">Select a policy to begin.</div></div></div></section><section id="approvals" class="view"><div class="panel"><h2>Approval queue</h2><p class="hint">Approval access depends on your assigned role. Approved policy publications can be activated here.</p><div id="approval-list" class="list"></div></div></section></main></div>
<dialog id="evidence-dialog"><div class="dialoghead"><h2 id="evidence-title">Evidence</h2><button id="close-evidence" type="button">Close</button></div><pre id="evidence-content"></pre></dialog><dialog id="action-dialog"><form id="action-form"><div class="dialoghead"><h2>Artifact operation</h2><button id="close-action" type="button">Close</button></div><div class="formbody"><input id="action-artifact" type="hidden"><label for="action-kind">Operation</label><select id="action-kind"><option value="quarantined">Quarantine</option><option value="revoked">Revoke</option><option value="rebuild">Queue rebuild</option><option value="distribute">Distribute</option><option value="promote">Promote</option><option value="approval">Request approval</option></select><label for="action-target">Target</label><input id="action-target" placeholder="Regions, bucket/channel, or approval resource"><label for="action-reason">Reason</label><textarea id="action-reason" required></textarea><label class="check"><input id="confirm-cost" type="checkbox"> I confirm possible cloud charges</label><button type="submit">Execute operation</button></div></form></dialog><script src="/console.js" defer></script></body></html>"""

CONSOLE_CSS = b""":root{--bg:#f3f5f7;--surface:#fff;--ink:#17202b;--muted:#5d6877;--line:#d8dee6;--nav:#15202d;--nav2:#202d3c;--accent:#1769aa;--accent2:#e7f1f9;--danger:#a23b3b;--warn:#946113;--ok:#18734d;--radius:8px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.skip{position:absolute;left:-9999px}.skip:focus{left:12px;top:12px;z-index:5;background:var(--surface);padding:8px}.topbar{height:64px;display:flex;align-items:center;justify-content:space-between;background:var(--nav);color:#f5f8fb;padding:0 22px}.brand{display:flex;align-items:center;gap:10px}.mark{display:grid;place-items:center;width:32px;height:32px;border:1px solid #6d8baa;border-radius:var(--radius);font-weight:800;color:#b7d9f4}.brand b,.brand small{display:block}.brand small{font:9px ui-monospace,monospace;letter-spacing:.12em;color:#94a7bb}.session{display:flex;align-items:center;gap:8px}.session label{font-size:11px;color:#b5c0cc}.session input,.filters input{border:1px solid #526477;border-radius:6px;background:var(--nav2);color:#fff;padding:8px 10px;min-width:210px}.session button,#refresh,.dialoghead button,.list button{border:1px solid transparent;border-radius:6px;background:var(--accent);color:#fff;padding:8px 12px;font-weight:700;cursor:pointer;white-space:nowrap}.session .secondary,.dialoghead button{background:transparent;border-color:#526477;color:#e6edf4}button:active{transform:translateY(1px)}button:focus-visible,input:focus-visible{outline:3px solid #7db7e2;outline-offset:2px}.shell{display:grid;grid-template-columns:210px minmax(0,1fr);min-height:calc(100dvh - 64px)}aside{background:var(--nav);padding:20px 12px;display:flex;flex-direction:column;justify-content:space-between}nav{display:grid;gap:4px}.nav{border:0;border-radius:6px;background:transparent;color:#b8c5d2;text-align:left;padding:10px 12px;cursor:pointer;font-weight:650}.nav:hover,.nav.active{background:var(--nav2);color:#fff}.connection{border-top:1px solid #314153;padding:16px 10px 4px;color:#95a6b7;font-size:12px}.connection.online{color:#88d3af}main{padding:28px;max-width:1500px;width:100%;margin:0 auto}.pagehead{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.pagehead h1{font-size:26px;letter-spacing:-.025em;margin:0}.pagehead p,.hint{margin:4px 0 0;color:var(--muted)}.notice{border:1px solid #bdd1e2;background:var(--accent2);padding:10px 12px;border-radius:var(--radius);margin-bottom:16px}.notice.error{border-color:#e3bbbb;background:#faecec;color:var(--danger)}.notice.loading{color:var(--muted);background:#edf0f3;border-color:var(--line)}.view{display:none}.view.active{display:block}.metrics{display:grid;grid-template-columns:repeat(5,1fr);border:1px solid var(--line);background:var(--surface);border-radius:var(--radius);margin-bottom:16px}.metrics article{padding:16px;border-right:1px solid var(--line)}.metrics article:last-child{border:0}.metrics span{display:block;color:var(--muted);font-size:11px}.metrics strong{font:750 28px/1.3 ui-monospace,monospace}.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:18px;min-width:0}.panel h2{font-size:16px;margin:0 0 14px}.panelhead{display:flex;align-items:flex-end;justify-content:space-between;gap:18px}.filters{display:flex;align-items:center;gap:7px}.filters label{font-size:11px;color:var(--muted)}.filters input{background:#fff;color:var(--ink);border-color:var(--line);min-width:160px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:720px}th,td{padding:11px 9px;text-align:left;border-bottom:1px solid var(--line)}th{font:700 10px ui-monospace,monospace;letter-spacing:.06em;color:var(--muted)}tbody tr{cursor:pointer}tbody tr:hover{background:#f7f9fb}.status{font-weight:700;color:var(--ok)}.status.quarantined{color:var(--warn)}.status.revoked,.status.error{color:var(--danger)}.masterdetail{display:grid;grid-template-columns:minmax(290px,.8fr) minmax(0,1.7fr);gap:16px}.list{display:grid;gap:1px;background:var(--line)}.listitem{background:var(--surface);padding:12px;border:0;text-align:left;color:var(--ink);cursor:pointer}.listitem:hover{background:#f3f7fa}.listitem strong,.listitem span,.listitem small{display:block}.listitem span{color:var(--muted)}.listitem small{font-family:ui-monospace,monospace;color:#718091}.detail{min-height:360px}.empty{color:var(--muted);padding:28px 8px;text-align:center}.kv{display:grid;grid-template-columns:140px 1fr;gap:7px 14px;margin-bottom:18px}.kv dt{color:var(--muted)}.kv dd{margin:0;overflow-wrap:anywhere}.evidence{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);padding:10px 0;gap:12px}.evidence button,.approval-actions button{padding:6px 9px;font-size:12px}.tree{font-family:ui-monospace,monospace;white-space:pre-wrap;background:#f5f7f9;border:1px solid var(--line);padding:12px;border-radius:6px}.approval-actions{margin-top:8px}.json{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7f9;border-radius:6px;padding:10px;font:11px/1.5 ui-monospace,monospace}dialog{width:min(900px,92vw);max-height:82dvh;border:1px solid var(--line);border-radius:var(--radius);padding:0;background:var(--surface);color:var(--ink)}dialog::backdrop{background:rgba(13,23,34,.55)}.dialoghead{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid var(--line)}.dialoghead h2{margin:0}.dialoghead button{color:var(--ink);border-color:var(--line)}dialog pre{margin:0;padding:18px;overflow:auto;max-height:65dvh;font:12px/1.55 ui-monospace,monospace}@media(max-width:980px){.shell{grid-template-columns:1fr}aside{display:block;padding:8px 12px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.connection{display:none}.metrics{grid-template-columns:repeat(2,1fr)}.metrics article{border-bottom:1px solid var(--line)}.masterdetail{grid-template-columns:1fr}.topbar{height:auto;padding:12px;gap:12px;align-items:flex-start}.session{flex-wrap:wrap;justify-content:flex-end}.session label{display:none}}@media(max-width:620px){main{padding:18px 10px}.topbar{display:block}.session{margin-top:10px;justify-content:flex-start}.metrics{grid-template-columns:1fr}.metrics article{border-right:0}.pagehead,.panelhead{align-items:flex-start;gap:12px}.filters{flex-wrap:wrap}.filters input{width:100%}.kv{grid-template-columns:1fr}.kv dd{margin-bottom:8px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}"""

CONSOLE_CSS += b""".formbody{display:grid;gap:8px;padding:18px}.formbody label{font-size:12px;color:var(--muted)}.formbody input,.formbody select,.formbody textarea{width:100%;border:1px solid var(--line);border-radius:6px;padding:9px;background:#fff;color:var(--ink)}.formbody textarea{min-height:80px;resize:vertical}.formbody .check{display:flex;align-items:center;gap:8px}.formbody .check input{width:auto}.actions{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}.actions button{border:1px solid var(--line);border-radius:6px;padding:7px 10px;background:#fff;color:var(--ink);cursor:pointer}.timeline{position:relative;display:grid;gap:0;margin:8px 0 20px;padding-left:18px}.timeline:before{content:"";position:absolute;left:6px;top:8px;bottom:8px;width:2px;background:var(--line)}.timeline-step{position:relative;padding:8px 10px 10px 14px;border-bottom:1px solid #edf0f3}.timeline-step:before{content:"";position:absolute;left:-17px;top:13px;width:9px;height:9px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 3px var(--surface)}.timeline-step.error:before{background:var(--danger)}.timeline-step strong,.timeline-step small{display:block}.timeline-step small{color:var(--muted);font:11px ui-monospace,monospace}.lineage-map{display:grid;gap:7px;margin-top:14px;padding:12px;background:#f6f8fa;border:1px solid var(--line);border-radius:6px}.lineage-node{position:relative;border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:5px;background:#fff;padding:8px 10px;max-width:520px}.lineage-node.revoked{border-left-color:var(--danger)}.lineage-node.quarantined{border-left-color:var(--warn)}.lineage-node small{display:block;color:var(--muted)}.section-title{font-size:13px;margin:18px 0 7px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.simulation{background:#f6f8fa;border:1px solid var(--line);border-radius:6px;padding:14px;margin-top:10px}.simulation-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.simulation-grid div{background:#fff;border:1px solid var(--line);padding:10px;border-radius:5px}.simulation-grid strong,.simulation-grid span{display:block}.simulation-grid strong{font:750 22px ui-monospace,monospace}.simulation-grid span{font-size:10px;color:var(--muted);text-transform:uppercase}.impact-row{display:grid;grid-template-columns:minmax(120px,1fr) 2fr 70px;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid var(--line)}.impact-bar{height:8px;background:#dce3e9;border-radius:99px;overflow:hidden}.impact-bar i{display:block;height:100%;background:var(--danger)}.policy-editor{display:block;width:100%;min-height:300px;margin-top:6px;padding:12px;resize:vertical;border:1px solid var(--line);border-radius:6px;background:#101820;color:#e8eef4;font:12px/1.55 ui-monospace,monospace}.detail>label{display:block;margin-top:10px;font-size:11px;color:var(--muted)}#policy-environment{border:1px solid var(--line);border-radius:6px;padding:8px;width:180px}.change{display:grid;grid-template-columns:100px minmax(130px,1fr) 1fr 1fr;gap:8px;padding:8px 0;border-bottom:1px solid var(--line);font:11px/1.4 ui-monospace,monospace}.exception-card{border-left:4px solid var(--ok);background:#fff;padding:10px;margin:7px 0}.exception-card.expiring{border-left-color:var(--warn)}.exception-card.expired{border-left-color:var(--danger)}@media(max-width:620px){.simulation-grid{grid-template-columns:repeat(2,1fr)}.impact-row,.change{grid-template-columns:1fr}}"""

CONSOLE_CSS += b""".metrics{grid-template-columns:repeat(9,1fr)}.trace-group{background:#fff;border:1px solid var(--line);padding:12px;margin:8px 0}.trace-span{display:grid;grid-template-columns:180px 1fr 85px;gap:8px;align-items:center;padding:5px 0}.trace-track{height:14px;background:#edf0f3;border-radius:3px;overflow:hidden}.trace-track i{display:block;height:100%;min-width:2px;background:var(--accent)}.trace-span.error .trace-track i{background:var(--danger)}.evidence-check{display:grid;grid-template-columns:130px 80px 1fr;gap:8px;padding:7px 0;border-bottom:1px solid var(--line)}@media(max-width:1100px){.metrics{grid-template-columns:repeat(3,1fr)}}@media(max-width:620px){.metrics{grid-template-columns:1fr}.trace-span,.evidence-check{grid-template-columns:1fr}}"""

CONSOLE_JS = br"""(() => {'use strict';let token='',artifacts=[],runs=[];const $=id=>document.getElementById(id);const titles={overview:['Operations overview','Current registry health and actionable platform state.'],runs:['Runs & evidence','Inspect execution state and preview attached evidence.'],traces:['Distributed traces','Follow request latency, parent spans and failures.'],lineage:['Artifact lineage','Inspect descendants, channels and rebuild blast radius.'],policies:['Policy registry','Review published, active and revoked policy bundles.'],approvals:['Approval queue','Review governance operations that require quorum.']};
function notice(message,kind=''){$('notice').textContent=message;$('notice').className='notice '+kind}function connected(value){$('connection').textContent=value?'Connected':'Disconnected';$('connection').classList.toggle('online',value)}function empty(container,message){container.textContent='';const div=document.createElement('div');div.className='empty';div.textContent=message;container.appendChild(div)}function badge(value){const span=document.createElement('span');span.className='status '+String(value||'').toLowerCase();span.textContent=value||'unknown';return span}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{...(options.headers||{}),Authorization:'Bearer '+token}});if(!response.ok){let message='HTTP '+response.status;try{const p=(await response.json()).error;message=typeof p==='string'?p:(p.message||message)}catch(_error){}throw new Error(message)}const type=response.headers.get('content-type')||'';return type.includes('json')?response.json():response.text()}
function item(container,title,meta,small,onClick){const button=document.createElement('button');button.type='button';button.className='listitem';const strong=document.createElement('strong');strong.textContent=title;const span=document.createElement('span');span.textContent=meta||'';const foot=document.createElement('small');foot.textContent=small||'';button.append(strong,span,foot);if(onClick)button.addEventListener('click',onClick);container.appendChild(button)}function kv(container,data){const dl=document.createElement('dl');dl.className='kv';Object.entries(data).forEach(([key,value])=>{const dt=document.createElement('dt');dt.textContent=key;const dd=document.createElement('dd');dd.textContent=value===undefined||value===null||value===''?'-':String(value);dl.append(dt,dd)});container.appendChild(dl)}
function renderArtifacts(rows){artifacts=rows;const body=$('artifact-rows');body.textContent='';const counts={active:0,quarantined:0};rows.forEach(doc=>{const tr=document.createElement('tr');[doc.artifact_id,doc.bucket,doc.version].forEach(v=>{const td=document.createElement('td');td.textContent=v||'-';tr.appendChild(td)});const td=document.createElement('td');td.appendChild(badge(doc.status));tr.appendChild(td);const date=document.createElement('td');date.textContent=doc.created_at||'-';tr.appendChild(date);tr.addEventListener('click',()=>showLineage(doc.artifact_id));body.appendChild(tr);if(Object.hasOwn(counts,doc.status))counts[doc.status]++});if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.className='empty';td.textContent='No artifacts in the current scope.';tr.appendChild(td);body.appendChild(tr)}$('total').textContent=String(rows.length);$('active').textContent=String(counts.active);$('quarantined').textContent=String(counts.quarantined);renderLineageList()}
function renderRuns(rows){runs=rows;const list=$('run-list');list.textContent='';rows.forEach(run=>item(list,run.run_id,[run.profile,run.status].filter(Boolean).join(' / '),run.created_at||run.state,()=>showRun(run.run_id)));if(!rows.length)empty(list,'No runs in the current scope.');$('run-count').textContent=String(rows.length)}
function heading(container,text){const h=document.createElement('h3');h.className='section-title';h.textContent=text;container.appendChild(h)}
function renderRunTimeline(container,run){heading(container,'Execution timeline');const timeline=document.createElement('div');timeline.className='timeline';const events=run.events||[];if(events.length){events.forEach(event=>{const step=document.createElement('div');step.className='timeline-step '+(String(event.to||event.status||'').includes('fail')?'error':'');const title=document.createElement('strong');title.textContent=(event.from?event.from+' -> ':'')+(event.to||event.type||event.event||'event');const meta=document.createElement('small');meta.textContent=[event.ts||event.at||'',event.actor||event.worker_id||'',event.reason||''].filter(Boolean).join(' / ');step.append(title,meta);timeline.appendChild(step)})}else{const checkpoints=run.checkpoints&&run.checkpoints.phases?run.checkpoints.phases:run.checkpoints||{};Object.entries(checkpoints).forEach(([name,value])=>{const step=document.createElement('div');step.className='timeline-step';const title=document.createElement('strong');title.textContent=name;const meta=document.createElement('small');meta.textContent=typeof value==='object'?String(value.completed_at||value.status||'completed'):String(value);step.append(title,meta);timeline.appendChild(step)})}if(!timeline.childElementCount){const step=document.createElement('div');step.className='timeline-step';step.textContent='No event or checkpoint timeline is attached.';timeline.appendChild(step)}container.appendChild(timeline)}
async function showRun(id){try{const result=await api('/api/v1/runs/'+encodeURIComponent(id)),run=result.run,out=$('run-detail');out.textContent='';kv(out,{Run:run.run_id,Profile:run.profile,Status:run.status,State:run.state,Mode:run.mode,Started:run.created_at,Evidence:run.evidence_count});renderRunTimeline(out,run);heading(out,'Evidence');(run.evidence||[]).forEach(ev=>{const row=document.createElement('div');row.className='evidence';const label=document.createElement('span');label.textContent=(ev.kind||'evidence')+': '+ev.path;const button=document.createElement('button');button.type='button';button.textContent='Preview';button.addEventListener('click',()=>showEvidence(id,ev.path));row.append(label,button);out.appendChild(row)});if(!(run.evidence||[]).length){const p=document.createElement('p');p.className='hint';p.textContent='No evidence files are attached.';out.appendChild(p)}}catch(error){notice(error.message,'error')}}
async function showEvidence(runId,path){try{const value=await api('/api/v1/runs/'+encodeURIComponent(runId)+'/evidence?path='+encodeURIComponent(path));$('evidence-title').textContent=path;$('evidence-content').textContent=typeof value==='string'?value:JSON.stringify(value,null,2);$('evidence-dialog').showModal()}catch(error){notice(error.message,'error')}}
function renderTraces(rows){const list=$('trace-list');list.textContent='';const groups={};rows.forEach(span=>(groups[span.trace_id||'unknown']??=[]).push(span));Object.entries(groups).forEach(([trace,spans])=>{const group=document.createElement('div');group.className='trace-group';const title=document.createElement('strong');title.textContent='Trace '+trace;group.appendChild(title);const max=Math.max(1,...spans.map(span=>Number(span.duration_ms||0)));spans.sort((a,b)=>Number(a.start_ns||0)-Number(b.start_ns||0)).forEach(span=>{const row=document.createElement('div');row.className='trace-span '+(span.status||'');const name=document.createElement('span');name.textContent=span.name||'span';const track=document.createElement('div');track.className='trace-track';const bar=document.createElement('i');bar.style.width=String((Number(span.duration_ms||0)/max)*100)+'%';track.appendChild(bar);const duration=document.createElement('small');duration.textContent=String(span.duration_ms||0)+' ms';row.append(name,track,duration);group.appendChild(row)});list.appendChild(group)});if(!rows.length)empty(list,'No trace spans recorded.')}
function renderLineageList(){const list=$('lineage-list');list.textContent='';artifacts.forEach(doc=>item(list,doc.artifact_id,doc.bucket+' / '+doc.version,doc.status,()=>showLineage(doc.artifact_id)));if(!artifacts.length)empty(list,'No artifacts available.')}
async function showLineage(id){switchView('lineage');try{const [artifact,impact,evidence]=await Promise.all([api('/api/v1/artifacts/'+encodeURIComponent(id)),api('/api/v1/artifacts/'+encodeURIComponent(id)+'/impact'),api('/api/v1/artifacts/'+encodeURIComponent(id)+'/evidence-summary')]),out=$('lineage-detail');out.textContent='';kv(out,{Artifact:artifact.artifact_id,Bucket:artifact.bucket,Version:artifact.version,Status:artifact.status,Descendants:impact.descendant_count,Channels:impact.channel_count,Evidence:evidence.passed+' passed / '+evidence.failed+' missing or failed'});const actions=document.createElement('div');actions.className='actions';['quarantined','revoked','rebuild','distribute','promote','approval'].forEach(kind=>{const button=document.createElement('button');button.type='button';button.textContent={quarantined:'Quarantine',revoked:'Revoke',rebuild:'Queue rebuild',distribute:'Distribute',promote:'Promote',approval:'Request approval'}[kind];button.addEventListener('click',()=>openAction(id,kind));actions.appendChild(button)});out.appendChild(actions);heading(out,'Evidence center');(evidence.checks||[]).forEach(check=>{const row=document.createElement('div');row.className='evidence-check';const name=document.createElement('strong');name.textContent=check.name;row.append(name,badge(check.passed?'pass':'missing'),document.createTextNode(check.value===undefined||check.value===null?'':String(check.value)));out.appendChild(row)});heading(out,'Blast radius map');const map=document.createElement('div');map.className='lineage-map';const nodes=(impact.artifacts||[]);nodes.forEach(row=>{const node=document.createElement('div');node.className='lineage-node '+String(row.status||'');node.style.marginLeft=Math.min(Number(row.depth||0)*28,196)+'px';const title=document.createElement('strong');title.textContent=row.artifact_id;const meta=document.createElement('small');meta.textContent='depth '+String(row.depth||0)+' / '+(row.status||'unknown');node.append(title,meta);map.appendChild(node)});if(!nodes.length){const node=document.createElement('div');node.className='lineage-node';node.textContent='No descendants';map.appendChild(node)}out.appendChild(map)}catch(error){notice(error.message,'error')}}
function openAction(id,kind){$('action-artifact').value=id;$('action-kind').value=kind;$('action-target').value='';$('action-reason').value='';$('confirm-cost').checked=false;$('action-dialog').showModal()}
async function submitAction(event){event.preventDefault();const id=$('action-artifact').value,kind=$('action-kind').value,target=$('action-target').value.trim(),reason=$('action-reason').value.trim(),headers={'Content-Type':'application/json'},operation='console-'+Date.now();let path,body,method='POST';if(kind==='quarantined'||kind==='revoked'){path='/api/v1/artifacts/'+encodeURIComponent(id)+'/status';method='PATCH';body={status:kind,reason}}else if(kind==='rebuild'){path='/api/v1/artifacts/'+encodeURIComponent(id)+'/rebuild';headers['Idempotency-Key']=operation;body={reason}}else if(kind==='distribute'){if(!$('confirm-cost').checked){notice('Cloud cost confirmation is required.','error');return}path='/api/v1/artifacts/'+encodeURIComponent(id)+'/distribute';headers['X-Confirm-Cost']='true';body={regions:target.split(',').map(value=>value.trim()).filter(Boolean)}}else if(kind==='promote'){const parts=target.split('/');if(parts.length!==2){notice('Promotion target must be bucket/channel.','error');return}path='/api/v1/channels/'+encodeURIComponent(parts[0])+'/'+encodeURIComponent(parts[1]);method='PUT';headers['Idempotency-Key']=operation;body={artifact_id:id}}else{path='/api/v1/approvals';body={action:'channel.promote',resource:target,payload:{artifact_id:id}}}try{await api(path,{method,headers,body:JSON.stringify(body)});$('action-dialog').close();notice('Operation accepted and audited.');await load()}catch(error){notice(error.message,'error')}}
function renderSimulation(container,result){container.textContent='';const title=document.createElement('h3');title.textContent='Dry-run impact / '+result.environment;container.appendChild(title);const grid=document.createElement('div');grid.className='simulation-grid';[['Allowed',result.summary.allowed],['Denied',result.summary.denied],['Newly allowed',result.summary.newly_allowed],['Newly denied',result.summary.newly_denied]].forEach(([label,value])=>{const box=document.createElement('div'),strong=document.createElement('strong'),span=document.createElement('span');strong.textContent=String(value);span.textContent=label;box.append(strong,span);grid.appendChild(box)});container.appendChild(grid);heading(container,'Denied controls');const max=Math.max(1,...Object.values(result.control_denials));Object.entries(result.control_denials).forEach(([control,count])=>{const row=document.createElement('div');row.className='impact-row';const label=document.createElement('span');label.textContent=control;const bar=document.createElement('div');bar.className='impact-bar';const fill=document.createElement('i');fill.style.width=String((Number(count)/max)*100)+'%';bar.appendChild(fill);const value=document.createElement('strong');value.textContent=String(count);row.append(label,bar,value);container.appendChild(row)});if(!Object.keys(result.control_denials).length){const p=document.createElement('p');p.className='hint';p.textContent='No artifacts would be denied.';container.appendChild(p)}heading(container,'Affected artifacts');(result.artifacts||[]).filter(row=>row.transition!=='unchanged'||!row.after_allowed).slice(0,100).forEach(row=>{const line=document.createElement('div');line.className='evidence';const label=document.createElement('span');label.textContent=row.artifact_id+' / '+row.transition;line.append(label,badge(row.after_allowed?'allowed':'denied'));container.appendChild(line)})}
async function simulatePublishedPolicy(record,container){container.textContent='Running dry-run simulation...';try{const result=await api('/api/v1/policies/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bundle:record.bundle,environment:'production'})});renderSimulation(container,result)}catch(error){empty(container,error.message)}}
function candidatePolicy(){try{return JSON.parse($('policy-editor').value)}catch(error){throw new Error('Candidate policy is not valid JSON: '+error.message)}}
function policyRequest(path){const bundle=candidatePolicy(),environment=$('policy-environment').value.trim()||'production';return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bundle,environment})})}
function renderDiff(result){const out=$('policy-result');out.textContent='';const title=document.createElement('h3');title.textContent=String(result.change_count)+' field changes';out.appendChild(title);(result.changes||[]).forEach(change=>{const row=document.createElement('div');row.className='change';[change.kind,change.path,JSON.stringify(change.before),JSON.stringify(change.after)].forEach(value=>{const cell=document.createElement('span');cell.textContent=value===undefined?'-':String(value);row.appendChild(cell)});out.appendChild(row)});if(!result.change_count)out.append('Candidate matches the active policy.')}
function renderExceptions(result){const out=$('policy-result');out.textContent='';const title=document.createElement('h3');title.textContent=String(result.exception_count)+' policy exceptions';out.appendChild(title);(result.exceptions||[]).forEach(item=>{const card=document.createElement('div');card.className='exception-card '+item.status;const strong=document.createElement('strong');strong.textContent=item.id+' / '+item.status;const meta=document.createElement('div');meta.textContent=String(item.days_remaining)+' days remaining / owner '+item.owner;const impact=document.createElement('small');impact.textContent=String(item.affected_artifact_count)+' artifacts would be denied after removal: '+(item.affected_artifacts||[]).join(', ');card.append(strong,meta,impact);out.appendChild(card)});if(!result.exception_count)out.append('No exceptions in this policy.')}
async function runPolicyTool(kind){const out=$('policy-result');out.textContent='Running '+kind+'...';try{if(kind==='diff')renderDiff(await policyRequest('/api/v1/policies/diff'));else if(kind==='exceptions')renderExceptions(await policyRequest('/api/v1/policies/exceptions/preview'));else renderSimulation(out,await policyRequest('/api/v1/policies/simulate'))}catch(error){empty(out,error.message)}}
async function requestPolicyPublication(){try{const bundle=candidatePolicy(),resource=String(bundle.policy_id)+'@'+String(bundle.version),payload={bundle,activate:true};const result=await api('/api/v1/approvals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'policy.publish',resource,payload})});notice('Publication approval requested: '+result.approval_id);await loadApprovals();switchView('approvals')}catch(error){notice(error.message,'error')}}
async function publishApproved(row){try{await api('/api/v1/policies/publish',{method:'POST',headers:{'Content-Type':'application/json','Approval-Id':row.approval_id},body:JSON.stringify(row.payload)});notice('Policy published and activated.');await load()}catch(error){notice(error.message,'error')}}
function renderPolicies(rows){const list=$('policy-list');list.textContent='';rows.forEach(row=>{const box=document.createElement('button');box.type='button';box.className='listitem';const title=document.createElement('strong');title.textContent=row.policy_id+'@'+row.version;box.append(title,badge(row.status));const meta=document.createElement('small');meta.textContent='Published by '+(row.published_by||'unknown');box.appendChild(meta);box.addEventListener('click',()=>{$('policy-editor').value=JSON.stringify(row.bundle||row,null,2);$('policy-result').textContent='Candidate loaded. Preview its diff and impact before publication.'});list.appendChild(box)});if(!rows.length)empty(list,'No policy bundles published.')}
function renderApprovals(rows){const list=$('approval-list');list.textContent='';rows.forEach(row=>{const box=document.createElement('div');box.className='listitem';const strong=document.createElement('strong');strong.textContent=row.action+' / '+row.resource;box.appendChild(strong,badge(row.status));const meta=document.createElement('small');meta.textContent=row.approval_id+' / '+String((row.approvals||[]).length)+' of '+row.required_approvals;box.appendChild(meta);if(row.status==='pending'){const actions=document.createElement('div');actions.className='approval-actions';const button=document.createElement('button');button.type='button';button.textContent='Approve';button.addEventListener('click',()=>approve(row.approval_id));actions.appendChild(button);box.appendChild(actions)}else if(row.status==='approved'&&row.action==='policy.publish'){const actions=document.createElement('div');actions.className='approval-actions';const button=document.createElement('button');button.type='button';button.textContent='Publish and activate';button.addEventListener('click',()=>publishApproved(row));actions.appendChild(button);box.appendChild(actions)}list.appendChild(box)});if(!rows.length)empty(list,'No approvals available.')}
async function approve(id){try{await api('/api/v1/approvals/'+encodeURIComponent(id)+'/approve',{method:'POST'});notice('Approval recorded.');await loadApprovals()}catch(error){notice(error.message,'error')}}async function loadApprovals(){try{const result=await api('/api/v1/approvals?limit=100');renderApprovals(result.approvals||[])}catch(error){empty($('approval-list'),error.message)}}
async function load(){if(!token){notice('Enter a Bearer token first.','error');return}notice('Loading authorized platform data.','loading');const qs=new URLSearchParams({limit:'200'}),bucket=$('bucket').value.trim(),search=$('artifact-search').value.trim();if(bucket)qs.set('bucket',bucket);if(search)qs.set('q',search);const results=await Promise.allSettled([api('/api/v1/artifacts?'+qs),api('/api/v1/runs?limit=200'),api('/api/v1/rebuild-requests?status=queued&limit=200'),api('/api/v1/traces?limit=100'),api('/api/v1/policies?limit=100'),api('/api/v1/dashboard?days=30')]);if(results[0].status==='rejected'){connected(false);notice(results[0].reason.message,'error');return}renderArtifacts(results[0].value.artifacts||[]);if(results[1].status==='fulfilled')renderRuns(results[1].value.runs||[]);if(results[2].status==='fulfilled')$('rebuild-count').textContent=String(results[2].value.count||0);if(results[3].status==='fulfilled')renderTraces(results[3].value.spans||[]);if(results[4].status==='fulfilled')renderPolicies(results[4].value.policies||[]);if(results[5].status==='fulfilled'){const snapshot=results[5].value.snapshot,p95=snapshot.duration_seconds.p95,replicas=snapshot.replicas||{};$('success-rate').textContent=snapshot.success_rate===null?'-':String(snapshot.success_rate)+'%';$('run-p95').textContent=p95===null?'-':String(p95)+'s';$('failed-runs').textContent=String(snapshot.runs.failed);$('replica-errors').textContent=String((replicas.failed||0)+(replicas.error||0))}await loadApprovals();connected(true);notice('Data is filtered to the current identity and authorized buckets.')}
function switchView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav').forEach(v=>v.classList.toggle('active',v.dataset.view===id));$('view-title').textContent=titles[id][0];$('view-copy').textContent=titles[id][1]}
document.querySelectorAll('.nav').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view)));$('session').addEventListener('submit',event=>{event.preventDefault();token=$('token').value;$('token').value='';load()});$('refresh').addEventListener('click',load);$('artifact-search').addEventListener('change',load);$('bucket').addEventListener('change',load);$('trace-search').addEventListener('change',async()=>{try{const id=$('trace-search').value.trim(),result=await api('/api/v1/traces?limit=100'+(id?'&trace_id='+encodeURIComponent(id):''));renderTraces(result.spans||[])}catch(error){notice(error.message,'error')}});$('policy-diff').addEventListener('click',()=>runPolicyTool('diff'));$('policy-simulate').addEventListener('click',()=>runPolicyTool('simulate'));$('exception-preview').addEventListener('click',()=>runPolicyTool('exceptions'));$('policy-request').addEventListener('click',requestPolicyPublication);$('disconnect').addEventListener('click',()=>{token='';connected(false);notice('Session cleared.');renderArtifacts([]);renderRuns([]);empty($('trace-list'),'Connect to load traces.');empty($('policy-list'),'Connect to load policies.');empty($('approval-list'),'Connect to load approvals.')});$('close-evidence').addEventListener('click',()=>$('evidence-dialog').close());$('close-action').addEventListener('click',()=>$('action-dialog').close());$('action-form').addEventListener('submit',submitAction);renderArtifacts([]);renderRuns([]);renderTraces([]);renderPolicies([]);renderApprovals([])})();"""
